import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/vcpkg%E3%81%A7Qt5.html","title":"vcpkgでQt5","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":3.99,"words":1196},"filePathRelative":"vcpkgでQt5.md"}`),a={name:`vcpkgでQt5.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="vcpkgでqt5" tabindex="-1"><a class="header-anchor" href="#vcpkgでqt5"><span>vcpkgでQt5</span></a></h1><p><a href="./Qt.html">Qt</a>, <a href="./vcpkg.html">vcpkg</a></p><p>qt5-webengineが鬼門らしい。割とメンテされていて、パッチも色々あるし、新しいMacへの対応もちゃんとしている模様。</p><h2 id="リンク集" tabindex="-1"><a class="header-anchor" href="#リンク集"><span>リンク集</span></a></h2><ul><li><a href="https://github.com/microsoft/vcpkg/pull/24660#issuecomment-1124329485" target="_blank" rel="noopener noreferrer">[qt5] Update to 5.15.4 by Osyotr · Pull Request #24660 · microsoft/vcpkg</a> Qt5をアップデートする手順</li><li><a href="https://github.com/microsoft/vcpkg/pull/43524/files" target="_blank" rel="noopener noreferrer">[qt5-webengine] fix spellcheck buildflags issue by rremilian · Pull Request #43524 · microsoft/vcpkg</a> qt5-webengineの適当なPR。関連ファイルを知る手頃な方法という事でリンクしておく。</li><li>vcpkgのパッケージ <ul><li><a href="https://vcpkg.link/ports/qt5-base" target="_blank" rel="noopener noreferrer">qt5-base - vcpkg.link: Vcpkg Ports and Packages Explorer</a></li><li><a href="https://vcpkg.link/ports/qt5" target="_blank" rel="noopener noreferrer">qt5 - vcpkg.link: Vcpkg Ports and Packages Explorer</a><ul><li>qt5-baseの後に個別に入れる場合にここから探す。qt5-webchannelなどとして入れられる。</li></ul></li><li><a href="https://vcpkg.link/ports/qt5-webengine" target="_blank" rel="noopener noreferrer">qt5-webengine - vcpkg.link: Vcpkg Ports and Packages Explorer</a> よくビルドが失敗する奴。</li></ul></li><li><a href="https://github.com/karino2/HelloQt5Vcpkg" target="_blank" rel="noopener noreferrer">karino2/HelloQt5Vcpkg: vcpkg Qt5 test project.</a> 動作を確認する一番簡単なプロジェクト <ul><li><a href="https://doc.qt.io/archives/qt-5.15/qtwidgets-mainwindows-application-example.html" target="_blank" rel="noopener noreferrer">Application Example - Qt Widgets 5.15.19</a> あたりからそれっぽいのを持ってきて動かす。</li></ul></li><li><a href="https://kenkyu-note.hatenablog.com/entry/2021/05/01/181500" target="_blank" rel="noopener noreferrer">vcpkgに関する備忘録。 - 賢朽脳瘏</a> qt5-baseだけdynamicにするやり方とか。</li></ul><h2 id="helloqt5的なプロジェクト" tabindex="-1"><a class="header-anchor" href="#helloqt5的なプロジェクト"><span>HelloQt5的なプロジェクト</span></a></h2><p>動作を確認するために基本的なプロジェクトを作ってみた。</p><ul><li><a href="https://github.com/karino2/HelloQt5Vcpkg" target="_blank" rel="noopener noreferrer">karino2/HelloQt5Vcpkg: vcpkg Qt5 test project.</a></li></ul><p><a href="https://doc.qt.io/archives/qt-5.15/qtexamplesandtutorials.html" target="_blank" rel="noopener noreferrer">Qt Examples And Tutorials - Qt 5.15</a> あたりからそれっぽいのを持ってきて動かしたい。 ソース的にはqtbaseの中にあるので取ってくる</p><p>5.15のものを持ってくるには以下のタグか？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">git clone git://code.qt.io/qt/qtbase.git --branch v5.15.18-lts-lgpl --depth 1</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>mainwindow.uiやqrcのある例がいいなぁ、と思い、tutorialsのnotepadに決定。 持ってきたらあっさり動く。</p><h3 id="qt-wrap-cppなどが使えるか" tabindex="-1"><a class="header-anchor" href="#qt-wrap-cppなどが使えるか"><span>qt_wrap_cppなどが使えるか？</span></a></h3><p>find_packageすると勝手に使えるっぽいな。 qt_standard_project_setupだけ使えない。</p><p>tool_chainの設定などはいらないっぽい。すばら。</p><h2 id="macbook-airでのビルドの作業ログ" tabindex="-1"><a class="header-anchor" href="#macbook-airでのビルドの作業ログ"><span>MacBook Airでのビルドの作業ログ</span></a></h2><p>MacBook Air、Tahoe 26.1でビルドしてみる。まだTahoeはサポートしてなさそうだが。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ cd vcpkg_dir</span>
<span class="line">$ ./vcpkg install qt5</span>
<span class="line">...</span>
<span class="line">Make Error at installed/arm64-osx/share/vcpkg-make/vcpkg_make.cmake:108 (message):</span>
<span class="line">  gperf currently requires the following programs from the system package</span>
<span class="line">  manager:</span>
<span class="line"></span>
<span class="line">      autoconf autoconf-archive automake libtoolize</span>
<span class="line"></span>
<span class="line"></span>
<span class="line"></span>
<span class="line">      On Debian and Ubuntu derivatives:</span>
<span class="line">          sudo apt install autoconf autoconf-archive automake libtool</span>
<span class="line">      On recent Red Hat and Fedora derivatives:</span>
<span class="line">          sudo dnf install autoconf autoconf-archive automake libtool</span>
<span class="line">      On Arch Linux and derivatives:</span>
<span class="line">          sudo pacman -S autoconf autoconf-archive automake libtool</span>
<span class="line">      On Alpine:</span>
<span class="line">          apk add autoconf autoconf-archive automake libtool</span>
<span class="line">      On macOS:</span>
<span class="line">          brew install autoconf autoconf-archive automake libtool</span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ふむふむ。という事でbrew installしてみよう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ ./vcpkg install qt5</span>
<span class="line">...</span>
<span class="line">CMake Error at scripts/cmake/vcpkg_execute_required_process.cmake:127 (message):</span>
<span class="line">    Command failed:</span>
<span class="line">    ....</span>
<span class="line">    Working Directory: /Users/karino2/source/vcpkg/buildtrees/qt5-base/arm64-osx-dbg</span>
<span class="line">    Error code: 3</span>
<span class="line">    See logs for more information:</span>
<span class="line">      /Users/karino2/source/vcpkg/buildtrees/qt5-base/config-arm64-osx-dbg-out.log</span>
<span class="line">      /Users/karino2/source/vcpkg/buildtrees/qt5-base/config-arm64-osx-dbg-err.log</span>
<span class="line"></span>
<span class="line">Call Stack (most recent call first):</span>
<span class="line">  ports/qt5-base/cmake/configure_qt.cmake:186 (vcpkg_execute_required_process)</span>
<span class="line">  ports/qt5-base/portfile.cmake:395 (configure_qt)</span>
<span class="line">  scripts/ports.cmake:206 (include)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>とかいうエラーが。ふむ。out.logをみると割とできてそう。err.logをみると以下がそれっぽいか？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">ERROR: The OpenGL functionality tests failed!</span>
<span class="line">You might need to modify the include and library search paths by editing QMAKE_INCDIR_OPENGL[_ES2],</span>
<span class="line">QMAKE_LIBDIR_OPENGL[_ES2] and QMAKE_LIBS_OPENGL[_ES2] in the mkspec for your platform.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>あー、OpenGLはXquarts入れてないと多分だめだろうな。とりあえず入ったのか？と見て回ってみるが、入ってはいなさそう。</p><p>と、web上でそれっぽいのを眺めていたら（<a href="https://github.com/microsoft/vcpkg/blob/master/ports/qt5-base/portfile.cmake#L247-L251" target="_blank" rel="noopener noreferrer">vcpkg/ports/qt5-base/portfile.cmake at master · microsoft/vcpkg</a>）、なんかtahoeの時の対応が入っているっぽいな。 git pullしてみよう。</p><p>お、それでvcpkg installしたらあっさり入ったっぽい？</p><p>webengineが入ってないっぽいな、とググってみたらqt5-webengineというのがあるらしい。という事でインストールしてみよう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ ./vcpkg install qt5-webengine</span>
<span class="line">Computing installation plan...</span>
<span class="line">qt5-webengine is only supported on &#39;!static&#39;, which does not match arm64-osx. This usually means that there are known build failures, or runtime problems, when building other platforms. To ignore this and attempt to build qt5-webengine anyway, rerun vcpkg with \`--allow-unsupported\`.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>おや、staticになっているのか。そもそもqt、staticになってる方が嬉しいという話はあるよなぁ。いや、LGPLだからdylibの方がいいのか。 まぁなんにせよqt5-webengineはstaticでは上手くいかないらしいとの事だしqt5もdynamicにしてみよう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ ./vcpkg install qt5:arm64-osx-dynamic</span>
<span class="line">....</span>
<span class="line">CMake Error at scripts/cmake/vcpkg_execute_build_process.cmake:134 (message):</span>
<span class="line">    Command failed: /usr/bin/make -j 11</span>
<span class="line">    Working Directory: /Users/karino2/source/vcpkg/buildtrees/qt5-graphicaleffects/arm64-osx-dynamic-dbg</span>
<span class="line">    See logs for more information:</span>
<span class="line">      /Users/karino2/source/vcpkg/buildtrees/qt5-graphicaleffects/package-build-arm64-osx-dynamic-dbg-out.log</span>
<span class="line">      /Users/karino2/source/vcpkg/buildtrees/qt5-graphicaleffects/package-build-arm64-osx-dynamic-dbg-err.log</span>
<span class="line"></span>
<span class="line">Call Stack (most recent call first):</span>
<span class="line">  scripts/cmake/vcpkg_build_qmake.cmake:3 (vcpkg_execute_build_process)</span>
<span class="line">  scripts/cmake/vcpkg_build_qmake.cmake:76 (z_run_jom_build)</span>
<span class="line">  installed/arm64-osx-dynamic/share/qt5/qt_build_submodule.cmake:11 (vcpkg_build_qmake)</span>
<span class="line">  installed/arm64-osx-dynamic/share/qt5/qt_submodule_installation.cmake:9 (qt_build_submodule)</span>
<span class="line">  ports/qt5-graphicaleffects/portfile.cmake:3 (qt_submodule_installation)</span>
<span class="line">  scripts/ports.cmake:206 (include)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ふむふむ。err.logをみると、qmlcachegenからロードされるはずのlibpng16d.16.50.0.dylibが見つからないと言われているな。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">ld: warning: search path &#39;/Users/karino2/source/vcpkg/installed/arm64-osx-dynamic/debug/lib/manual-link&#39; not found</span>
<span class="line">dyld[91096]: Library not loaded: @rpath/libpng16d.16.50.0.dylib</span>
<span class="line">  Referenced from: &lt;0429EB76-C64C-32E4-BCE9-4CDA6E2D3125&gt; /Users/karino2/source/vcpkg/packages/qt5-declarative_arm64-osx-dynamic/tools/qt5/debug/bin/qmlcachegen</span>
<span class="line">  Reason: tried: &#39;/Users/karino2/source/vcpkg/packages/qt5-declarative_arm64-osx-dynamic/tools/qt5/debug/bin/../../../../debug/lib/libpng16d.16.50.0.dylib&#39; (no such file), &#39;/Users/karino2/source/vcpkg/packages/qt5-declarative_arm64-osx-dynamic/tools/qt5/debug/bin/../../../../debug/lib/libpng16d.16.50.0.dylib&#39; (no such file)</span>
<span class="line">make[3]: *** [../../../qml/QtGraphicalEffects/private/GaussianMaskedBlur.qmlc] Abort trap: 6</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>この<code>.././</code>がいっぱいあってdebug/libとなっている場所は、<code>vcpkg/packages/qt5-declarative_arm64-osx-dynamic/debug/lib</code>だった。 そしてそこにはlibpng16dはなかった。</p><p>ってqt5-declarativeってqmlのことかな？これはいらないな。</p><p>qt5-baseに入っているのは以下か。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">qt5-base provides pkg-config modules:</span>
<span class="line"></span>
<span class="line">  # Qt Concurrent module</span>
<span class="line">  Qt5Concurrent</span>
<span class="line"></span>
<span class="line">  # Qt Core module</span>
<span class="line">  Qt5Core</span>
<span class="line"></span>
<span class="line">  # Qt DBus module</span>
<span class="line">  Qt5DBus</span>
<span class="line"></span>
<span class="line">  # Qt Gui module</span>
<span class="line">  Qt5Gui</span>
<span class="line"></span>
<span class="line">  # Qt Network module</span>
<span class="line">  Qt5Network</span>
<span class="line"></span>
<span class="line">  # Qt OpenGL module</span>
<span class="line">  Qt5OpenGL</span>
<span class="line"></span>
<span class="line">  # Qt OpenGLExtensions module</span>
<span class="line">  Qt5OpenGLExtensions</span>
<span class="line"></span>
<span class="line">  # Qt PrintSupport module</span>
<span class="line">  Qt5PrintSupport</span>
<span class="line"></span>
<span class="line">  # Qt Sql module</span>
<span class="line">  Qt5Sql</span>
<span class="line"></span>
<span class="line">  # Qt Unit Testing Library</span>
<span class="line">  Qt5Test</span>
<span class="line"></span>
<span class="line">  # Qt Widgets module</span>
<span class="line">  Qt5Widgets</span>
<span class="line"></span>
<span class="line">  # Qt Xml module</span>
<span class="line">  Qt5Xml</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>で、qt5に入っているのは以下か。</p><p><a href="https://vcpkg.link/ports/qt5" target="_blank" rel="noopener noreferrer">qt5 - vcpkg.link: Vcpkg Ports and Packages Explorer</a></p><p>えーと、webchannelとwebengineをとりあえず使っているので足してみるか。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ ./vcpkg install qt5-webchannel:arm64-osx-dynamic</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>これは上手くいった。</p><h3 id="qt5-webengine" tabindex="-1"><a class="header-anchor" href="#qt5-webengine"><span>qt5-webengine</span></a></h3><p>上手くいってない。リンクをいくつか貼っておく。</p><ul><li><a href="https://github.com/microsoft/vcpkg/pull/48298/files" target="_blank" rel="noopener noreferrer">qt5-base: Fix build error on macOS 26 Tahoe by phoerious · Pull Request #48298 · microsoft/vcpkg</a> これと同じような事が必要か？</li><li><a href="https://github.com/microsoft/vcpkg/pull/48098" target="_blank" rel="noopener noreferrer">[qt5] Update to 5.15.18 by Osyotr · Pull Request #48098 · microsoft/vcpkg</a> これをみるとまだqt5-webengineが動いていないのはknwon issueの模様。直してもいいかもしれない。</li></ul><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ ./vcpkg install qt5-webengine:arm64-osx-dynamic</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>これはエラー。ログをみると、<code>libs.webengine-icu</code>がfailとか言われている。</p><p>icuが入ってないのかな？とみてみるが入っていそう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ ./vcpkg list icu</span>
<span class="line">icu:arm64-osx                                     78.1                Mature and widely used Unicode and localization ...</span>
<span class="line">icu:arm64-osx-dynamic                             78.1                Mature and widely used Unicode and localization ...</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>でもエラーログをみていると以下と書いてある。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Checking for icu &gt;= 65... no</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>おや、78.1と言っているが。</p><p>色々試したが良くわからん。なお、qt5-webviewは入れられた。別にこれでもいい気もするな。</p><h3 id="少しいじってみたが根が深そう" tabindex="-1"><a class="header-anchor" href="#少しいじってみたが根が深そう"><span>少しいじってみたが根が深そう</span></a></h3><p>少しビルドを通せないかパッチを作ってみようとしたが厳しそう。</p><ul><li>zutil.hのfdopenを削除</li><li>mojo関連のimport impを削除</li></ul><p>で、perfettoのテンプレートエラーまで来た。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">In file included from ../../../../src/5.15.18-eb2c6a0533/src/3rdparty/chromium/third_party/perfetto/src/tracing/track.cc:20:</span>
<span class="line">../../../../src/5.15.18-eb2c6a0533/src/3rdparty/chromium/third_party/perfetto/include/perfetto/tracing/internal/track_event_data_source.h:110:20: error: a template argument list is expecte</span>
<span class="line">d after a name prefixed by the template keyword [-Wmissing-template-arg-list-after-template-kw]</span>
<span class="line">  110 |     Base::template Trace([](typename Base::TraceContext ctx) { ctx.Flush(); });</span>
<span class="line">      |                    ^</span>
<span class="line">../../../../src/5.15.18-eb2c6a0533/src/3rdparty/chromium/third_party/perfetto/include/perfetto/tracing/internal/track_event_data_source.h:124:20: error: a template argument list is expecte</span>
<span class="line">d after a name prefixed by the template keyword [-Wmissing-template-arg-list-after-template-kw]</span>
<span class="line">  124 |     Base::template Trace([&amp;](typename Base::TraceContext ctx) {</span>
<span class="line">      |                    ^</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>この手のエラーが結構多い。DataSourceのTraceにテンプレート引数が追加であるのか？という雰囲気だが、チラッと見たらlambdaの引数があるだけで、引数で解決しそうにも見える。そして結構似たようなのの数が多い。</p><p>最近のコードと見比べたが結構違っていて、うーん、これを直すのは大変かな〜という気分になった。</p><p>Qt5ではqt5-webviewを使うようにする方が長生きするんじゃないかな？</p><h2 id="windowsでのビルドの作業ログ" tabindex="-1"><a class="header-anchor" href="#windowsでのビルドの作業ログ"><span>Windowsでのビルドの作業ログ</span></a></h2><p>WindowsはDeveloper Powershellに入っているvcpkgを使いたいのでマニフェストモードになるよなぁ、と思ってどうするのがいいかgeminiに聞いたら、 バイナリキャッシュを指定しろ、と言われる。ふむふむ。＞<a href="./vcpkg.html">vcpkg</a></p><p>とりあえず指定した。なんかきいてないな。でもデフォルトの挙動で良さそうな気がするので指定をやめる。</p><h3 id="マニフェストモードでqt5-baseを入れてみる" tabindex="-1"><a class="header-anchor" href="#マニフェストモードでqt5-baseを入れてみる"><span>マニフェストモードでqt5-baseを入れてみる</span></a></h3><p>とりあえずさっきMac用につくったHelloQt5VcpkgをWindows上でビルドしてみよう。 vcpkg.json作ってなかったので、適当に作ってコミットする。</p><p>そして以下を実行するとqt5-baseのビルドでエラーになる</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">PS&gt; mkdir build</span>
<span class="line">PS&gt; cmake . -B build -G &quot;Visual Studio 17 2022&quot; -A x64</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>なんかfreetypeのあたりで失敗しているが、イマイチ良くわからないな。</p><p>issueを眺めていたら、似たような現象がsubstコマンド使ったら治ったというのを見つける。</p><p><a href="https://github.com/microsoft/vcpkg/issues/47501" target="_blank" rel="noopener noreferrer">[qt5-base] build error on x64-windows · Issue #47501 · microsoft/vcpkg</a></p><p>substというのは特定のディレクトリをドライブレターに割り当てるコマンドっぽいな。なんか昔こういうの良く使ってた気がするが。 とりあえずやってみよう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">PS&gt; subst P: $PWD</span>
<span class="line">PS&gt; cd P:</span>
<span class="line">PS&gt; cmake . -B build -G &quot;Visual Studio 17 2022&quot; -A x64</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>お、なんか上手くいった風味だな。マジか。エラーメッセージからはめちゃわかりにくいな、これ。</p><p>続いてビルドして実行。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">PS&gt; cmake --build ./build --config Debug</span>
<span class="line">PS&gt; ./build/Debug/HelloQt5Vcpkg.exe</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>おお、出来た。</p><h3 id="マニフェストモードでのmacの振る舞い" tabindex="-1"><a class="header-anchor" href="#マニフェストモードでのmacの振る舞い"><span>マニフェストモードでのMacの振る舞い</span></a></h3><p>バイナリキャッシュ、WindowsだとAppData下が使われてくれているが、Macで手でcloneしたものだとそのディレクトリを使ってくれるんだろうか？ 試してみよう。</p><p>windows側でvcpkg.jsonを作成したプロジェクトをgit pullしてもうちどninjaをジェネレートしてみる。</p><p>お、なんかVCPKG_ROOTの下のbuildtreesとかが使われそうな雰囲気だな（ただ使ってるライブラリのハッシュが変わったので作り直しているっぽい）。</p><h2 id="qt5-webview" tabindex="-1"><a class="header-anchor" href="#qt5-webview"><span>qt5-webview</span></a></h2><p>WebEngineはビルドが困難過ぎるので、webviewで行ってみる。なんか一発で通ってしまった。</p><h2 id="プラグイン関連" tabindex="-1"><a class="header-anchor" href="#プラグイン関連"><span>プラグイン関連</span></a></h2><p>qt_add_pluginが無いが、add_libraryをSHAREDでやって、target_link_librariesでQt5::Widgetsを指定すれば良さそうか？</p><p><a href="https://stackoverflow.com/questions/30628593/using-cmake-with-qt5-and-qt-plugins" target="_blank" rel="noopener noreferrer">c++ - Using CMake with Qt5 and Qt Plugins - Stack Overflow</a></p>`,84)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};